export const CONSULTATION_TEST_TEMPLATES = {
  meeting_transcription_internal_tool: `## プロジェクト概要
社内ミーティングの音声を文字起こしして保存する社内ツール。録音された会議音声を入力すると自動でテキスト化し、議事録作成や会議内容の記録・共有に利用する。社内会議には機密情報が含まれる可能性があるため、外部クラウドに音声データを送信しないローカル処理を基本方針とする。

## 想定ユーザー
- 経営・マネジメント（会議記録の確認）
- プロジェクトマネージャー（決定事項やTODO整理）
- 制作チーム（制作ミーティングの記録）
- 営業（商談や打ち合わせ内容の記録）

## 解決したい課題
- 会議の議事録作成が手作業で行われている
- 会議内容が個人メモや録音ファイルに分散している
- 決定事項やTODOを整理するのに時間がかかる
- 過去会議の内容を探すのが難しい

## 最初に作るべきもの
音声ファイルを入力すると自動で文字起こしを行い、テキストファイルとして保存するシンプルなツール。最初の機能は「音声ファイル入力」「文字起こし」「テキスト保存」の3点に限定する。

## 扱うデータ
入力データ
- 会議音声ファイル（wav / m4a / mp3 など）
- 会議タイトル
- 会議日時

出力データ
- 文字起こしテキスト
- 会議ログテキスト
- 議事録（Markdown形式で保存する想定）

## 外部連携候補
- Google Drive（議事録ファイル共有）
- Slack（議事録通知や共有）
- Notion（会議ログやナレッジ整理）
- Google Calendar（会議と議事録の紐付け）

## 未確定事項
- リアルタイム文字起こしが必要か、録音後処理のみでよいか
- 話者分離機能を初期スコープに含めるか
- ツールのUI形式（CLI / Web UI / 社内既存ツール統合）
- 議事録生成を自動化するかどうか
- 議事録ファイルの保存場所（ローカル保存か社内共有ストレージか）

## RepoGenesis入力候補
社内ミーティング音声を文字起こしして議事録作成を支援する社内ツール。音声ファイルを入力すると自動でテキスト化し、会議内容を記録・共有できる仕組みを作る。初期機能は音声入力、文字起こし、テキスト保存の3点とする。`,
} as const;

export type ConsultationTestTemplateId = keyof typeof CONSULTATION_TEST_TEMPLATES;

export function getConsultationTestTemplate(id: ConsultationTestTemplateId): string {
  return CONSULTATION_TEST_TEMPLATES[id];
}
